export interface AgentRuntime {
  id: string;
  name: string;
  /** 检测出的系别：claude | codex | custom（按 Agent 自报的名字，不看是哪一条） */
  kind: string;
  /** Momoko 下载并更新 */
  managed: boolean;
  command: string;
  ready: boolean;
  /** Agent 自报的名字和版本（agentInfo） */
  agentName: string;
  error: string;
  detectedAt:
    | Date
    | undefined;
  /** 有进程在跑的会话数 */
  activeSessions: number;
  /** 正在下载或更新 */
  installing: boolean;
  caps:
    | AgentCapabilities
    | undefined;
  /** 服务器上已有的登录（没有为空）：账号名称和说明 */
  authLabel: string;
  /** 内置的两条（Claude Code、Codex）：不能移除，命令固定 */
  builtin: boolean;
  /** 能「Momoko 下载并更新」：只有带单文件发行包的（Claude Code） */
  canInstall: boolean;
  agentVersion: string;
  authDetail: string;
  /** 最近一次检查时服务器上已经登录（能开会话）；没登录时选择器里没有「服务器上的登录」 */
  loggedIn: boolean;
  /** 检查时 Agent 给的模型和每个模型的推理强度 */
  models: AgentModelOption[];
  /** 启动参数（command 是可执行文件） */
  args: string[];
}

